25  async function request<T>(path: string, init?: RequestInit): Promise<T> {
26    const response = await fetch(`${apiBaseUrl}${path}`, {
27      ...init,
28      headers: {
29        "Content-Type": "application/json",
30        ...init?.headers,
31      },
32    });
33    if (!response.ok) {
34      const payload = (await response.json().catch(() => null)) as { detail?: string } | null;
35      throw new ApiError(payload?.detail ?? `Request failed (${response.status})`, response.status);
36    }
37    return (await response.json()) as T;
