13  export function useCaseActivities(caseRef: string) {
14    const [activities, setActivities] = useState<ActivityEvent[]>([]);
15    const [unavailable, setUnavailable] = useState(false);
16  
17    useEffect(() => {
18      let disposed = false;
19      let source: EventSource | undefined;
20      const seen = new Set<string>();
21  
22      function add(batch: ActivityEvent[]) {
23        const fresh = batch.filter((activity) => !seen.has(activity.event_id));
24        if (!fresh.length) return;
25        for (const activity of fresh) seen.add(activity.event_id);
26        setActivities((current) => [...current, ...fresh].sort((left, right) => left.seq - right.seq));
27      }
28  
29      async function start() {
30        let cursor = 0;
31        for (;;) {
32          const page = await getCaseActivities(caseRef, cursor);
33          if (disposed) return;
34          add(page.events);
35          cursor = page.next_cursor;
36          if (!page.has_more) break;
37        }
38        source = new EventSource(caseActivitiesStreamUrl(caseRef, cursor));
39        source.onopen = () => setUnavailable(false);
40        source.onerror = () => {
41          if (!disposed) setUnavailable(true);
42        };
43        source.addEventListener("activity", (message) => {
44          if (typeof message.data === "string") add([JSON.parse(message.data) as ActivityEvent]);
45        });
46      }
